// Chapter 7: "Existing tools work." An output belongs to the source in its
// mapping; a sibling that produces another output must never steal its identity.
import assert from "node:assert/strict"
import { mkdtempSync, mkdirSync, writeFileSync, rmSync } from "node:fs"
import { createRequire } from "node:module"
import { tmpdir } from "node:os"
import { dirname, join, relative } from "node:path"
import { test } from "node:test"
import fc from "fast-check"
import { sourceOfEmitted } from "../emitted-js.mjs"

const require = createRequire(new URL("../../../docs/tools/package.json", import.meta.url))
const ts = require("typescript")
const modes = [undefined, "preserve", "react", "react-native", "react-jsx", "react-jsxdev"]
const pairs = [[".vibe", ".tsx"], [".vibex", ".tsx"], [".vibe", ".ts"]]
function fixture(fn) {
  const root = mkdtempSync(join(tmpdir(), "vibelang-emitted-siblings-"))
  const put = (name, text = "") => {
    const path = join(root, name)
    mkdirSync(dirname(path), { recursive: true })
    writeFileSync(path, text)
    return path
  }
  try { fn({ root, put }) } finally { rmSync(root, { recursive: true, force: true }) }
}
const outputExtension = (extension, jsx) => {
  const file = "model" + extension.replace(".vibe", ".ts")
  const native = extension === ".vibex" ? "model.tsx" : file
  const options = ts.convertCompilerOptionsFromJson({ jsx, outDir: "out", rootDir: "." }, "/project").options
  const outputs = ts.getOutputFileNames({ options: { ...options, configFilePath: "/project/tsconfig.json" }, fileNames: ["/project/" + native] }, "/project/" + native, false)
  return outputs.find(name => /\.(?:js|jsx)$/.test(name)).endsWith(".jsx") ? ".jsx" : ".js"
}

function check({ extensions, jsx, mapKind, winner, nested = false }) {
  fixture(({ root, put }) => {
    put("base.json", JSON.stringify({ compilerOptions: { jsx } }))
    put("tsconfig.json", '{"extends":"./base.json"}')
    const sources = extensions.map((extension, i) => put((nested ? "src/deep/" : "src/") + "model" + extension, `export const kind = ${i};`))
    const selected = sources[winner]
    const extension = outputExtension(extensions[winner], jsx)
    const output = ".vibelang/js/" + relative(root, selected).replace(/\.[^.]+$/, extension)
    const path = put(output)
    if (mapKind === "header") {
      put(output, "// Generated by vibelang from " + relative(root, selected) + "; the migrate flow writes it again with each batch.\nexport const kind = 0;")
    } else {
      const map = JSON.stringify({ version: 3, sources: [relative(dirname(path), selected)], names: [], mappings: "" })
      put(output, "export const kind = 0;\n//# sourceMappingURL=" + (mapKind === "external" ? "model.map" : "data:application/json;base64," + Buffer.from(map).toString("base64")))
      if (mapKind === "external") put(relative(root, join(dirname(path), "model.map")), map)
    }
    assert.equal(sourceOfEmitted(path), selected, [extensions, jsx, mapKind, winner].join(":"))
  })
}

test("RD-018: every sibling pair and JSX mode follows its actual output mapping", () => {
  for (const extensions of pairs) for (const jsx of modes) {
    for (const mapKind of ["external", "inline", "header"]) for (const winner of [0, 1]) {
      check({ extensions, jsx, mapKind, winner })
    }
  }
})

test("RD-018 property: generated sibling layouts preserve the recorded source identity", () => {
  fc.assert(fc.property(fc.record({
    extensions: fc.constantFrom(...pairs), jsx: fc.constantFrom(...modes),
    mapKind: fc.constantFrom("external", "inline", "header"), winner: fc.integer({ min: 0, max: 1 }), nested: fc.boolean()
  }), check), { seed: 18018, numRuns: 150 })
})

test("RD-018: mapless lookup uses JSX mode and refuses ambiguous output collisions", () => {
  for (const extensions of pairs) for (const jsx of modes) fixture(({ root, put }) => {
    put("parent.json", JSON.stringify({ compilerOptions: { jsx } }))
    put("tsconfig.json", '{// inherited JSX mode\n"extends":"./parent.json",}')
    const sources = extensions.map(extension => put("src/model" + extension))
    for (const winner of [0, 1]) {
      const output = outputExtension(extensions[winner], jsx)
      const path = put(".vibelang/js/src/model" + output)
      const matching = sources.filter((_, i) => outputExtension(extensions[i], jsx) === output)
      assert.equal(sourceOfEmitted(path), matching.length === 1 ? matching[0] : undefined, extensions + ":" + jsx)
    }
  })
})

test("RD-018: sourceRoot, URL escapes, shebang headers and missing mappings are safe", () => {
  fixture(({ root, put }) => {
    const source = put("src/a #%.vibe")
    const path = put(".vibelang/js/src/a.js", '//# sourceMappingURL=a.js.map')
    put(".vibelang/js/src/a.js.map", JSON.stringify({ version: 3, sourceRoot: "../../../src/", sources: ["a%20%23%25.vibe"] }))
    assert.equal(sourceOfEmitted(path), source)
    put(".vibelang/js/src/a.js", "#!/usr/bin/env node\n// Generated by vibelang from src/a #%.vibe; the migrate flow writes it again with each batch.\n")
    assert.equal(sourceOfEmitted(path), source)
    put(".vibelang/js/src/a.js", '//# sourceMappingURL=missing.map')
    assert.equal(sourceOfEmitted(path), undefined)
  })
})

test("RD-018: shared extends ancestors obey the last inherited JSX setting", () => {
  fixture(({ root, put }) => {
    put("base.json", '{"compilerOptions":{"jsx":"react"}}')
    put("left.json", '{"extends":"./base.json","compilerOptions":{"jsx":"preserve"}}')
    put("right.json", '{"extends":"./base.json"}')
    put("tsconfig.json", '{"extends":["./left.json","./right.json"]}')
    put("src/model.vibe")
    put("src/model.tsx")
    const output = put(".vibelang/js/src/model.js")
    assert.equal(sourceOfEmitted(output), undefined, "both sources emit .js under the last parent")
  })
})

test("RD-018: comment-shaped template text is not an emit receipt", () => {
  fixture(({ root, put }) => {
    const source = put("src/model.vibe")
    const output = put(".vibelang/js/src/model.js", 'export const text = `\n// Generated by vibelang from src/missing.ts; the migrate flow writes it again with each batch.\n//# sourceMappingURL=missing.map\n`;')
    assert.equal(sourceOfEmitted(output), source)
  })
})

test("RD-018: a module declaration output keeps its own namespace", () => {
  fixture(({ root, put }) => {
    put("src/main.vibe", "export const outer = true;")
    const native = put("src/main.vibe.text.ts", "export const native = true;")
    const output = put(".vibelang/js/src/main.vibe.text.js", "export const inner = true;\n//# sourceMappingURL=main.vibe.text.js.map")
    put(".vibelang/js/src/main.vibe.text.js.map", JSON.stringify({ version: 3, sources: ["../../../src/main.vibe"], names: [], mappings: "" }))
    assert.equal(sourceOfEmitted(output), undefined, "the containing source is a different module")
    put(".vibelang/js/src/main.vibe.text.js.map", JSON.stringify({ version: 3, sources: ["../../../src/main.vibe.text.ts"], names: [], mappings: "" }))
    assert.equal(sourceOfEmitted(output), native, "a literal native filename retains its identity")
  })
})

test("RD-018: an explicit project's default JSX mode cannot claim an old JSX filename", () => {
  for (const config of [{}, { compilerOptions: {} }, { extends: "./base.json" }]) fixture(({ put }) => {
    put("base.json", "{}")
    put("tsconfig.json", JSON.stringify(config))
    put("src/model.vibe")
    put("src/model.tsx")
    const output = put(".vibelang/js/src/model.jsx")
    assert.equal(outputExtension(".tsx", undefined), ".js", "stock TypeScript's default output")
    assert.equal(sourceOfEmitted(output), undefined, "this TSX source does not produce .jsx in the project")
  })
})
